namespace bptree {

class Node {
public:
    bool isLeaf;
    std::vector<int> keys;
    Node* ptr2next;
    union ptr {
        std::vector<Node*> ptr2Tree;
        std::vector<FILE*> dataPtr;
        ptr() {}
        ~ptr() {}
    } ptr2TreeOrData;

    Node() {
        this->isLeaf = false;
        this->ptr2next = NULL;
    }
};

// Reference implementations extracted from original B-Plus-Tree repository

// From search.cpp - searches for key in tree
bool search_key(Node* root, int key) {
    if (root == NULL) {
        return false;
    }

    Node* cursor = root;
    while (cursor->isLeaf == false) {
        int idx = std::upper_bound(cursor->keys.begin(), cursor->keys.end(), key) - cursor->keys.begin();
        cursor = cursor->ptr2TreeOrData.ptr2Tree[idx];
    }

    int idx = std::lower_bound(cursor->keys.begin(), cursor->keys.end(), key) - cursor->keys.begin();

    if (idx == cursor->keys.size() || cursor->keys[idx] != key) {
        return false;
    }

    return true;
}

// From insertion.cpp - finds leaf node where key should be inserted
Node* find_leaf_node(Node* root, int key) {
    if (root == NULL) {
        return NULL;
    }

    Node* cursor = root;
    while (cursor->isLeaf == false) {
        int idx = std::upper_bound(cursor->keys.begin(), cursor->keys.end(), key) - cursor->keys.begin();
        cursor = cursor->ptr2TreeOrData.ptr2Tree[idx];
    }

    return cursor;
}

// From insertion.cpp - finds position to insert key in sorted keys vector
int find_insert_position(const std::vector<int>& keys, int key) {
    int i = std::upper_bound(keys.begin(), keys.end(), key) - keys.begin();
    return i;
}

// From insertion.cpp - inserts key into leaf maintaining sorted order
void insert_into_sorted_leaf(Node* leaf, int key, FILE* filePtr) {
    if (leaf == NULL) return;

    int i = std::upper_bound(leaf->keys.begin(), leaf->keys.end(), key) - leaf->keys.begin();
    leaf->keys.push_back(key);
    leaf->ptr2TreeOrData.dataPtr.push_back(filePtr);

    if (i != leaf->keys.size() - 1) {
        for (int j = leaf->keys.size() - 1; j > i; j--) {
            leaf->keys[j] = leaf->keys[j - 1];
            leaf->ptr2TreeOrData.dataPtr[j] = leaf->ptr2TreeOrData.dataPtr[j - 1];
        }

        leaf->keys[i] = key;
        leaf->ptr2TreeOrData.dataPtr[i] = filePtr;
    }
}

// From utils.cpp - finds first (leftmost) leaf node
Node* find_first_leaf(Node* root) {
    if (root == NULL) return NULL;

    Node* cursor = root;
    if (cursor->isLeaf)
        return cursor;

    for (int i = 0; i < cursor->ptr2TreeOrData.ptr2Tree.size(); i++)
        if (cursor->ptr2TreeOrData.ptr2Tree[i] != NULL)
            return find_first_leaf(cursor->ptr2TreeOrData.ptr2Tree[i]);

    return NULL;
}

// From utils.cpp - finds parent of given child node
static Node* parent_result = NULL;

Node** find_parent(Node* root, Node* child) {
    if (root == NULL || child == NULL) {
        return NULL;
    }

    if (root->isLeaf) {
        return NULL;
    }

    if (root->ptr2TreeOrData.ptr2Tree.empty()) {
        return NULL;
    }

    if (root->ptr2TreeOrData.ptr2Tree[0] == NULL || root->ptr2TreeOrData.ptr2Tree[0]->isLeaf) {
        return NULL;
    }

    for (int i = 0; i < root->ptr2TreeOrData.ptr2Tree.size(); i++) {
        if (root->ptr2TreeOrData.ptr2Tree[i] == child) {
            parent_result = root;
            return &parent_result;
        }
    }

    for (int i = 0; i < root->ptr2TreeOrData.ptr2Tree.size(); i++) {
        Node* tmpCursor = root->ptr2TreeOrData.ptr2Tree[i];
        if (tmpCursor != NULL && !tmpCursor->isLeaf) {
            Node** result = find_parent(tmpCursor, child);
            if (result != NULL) {
                return result;
            }
        }
    }

    return NULL;
}

// From display.cpp - counts total keys at specific level (0-indexed)
int count_keys_in_level(Node* root, int level) {
    if (root == NULL) return 0;

    std::queue<Node*> q;
    q.push(root);
    int currentLevel = 0;
    int keyCount = 0;

    while (!q.empty()) {
        int sz = q.size();

        if (currentLevel == level) {
            for (int i = 0; i < sz; i++) {
                Node* u = q.front();
                q.pop();
                keyCount += u->keys.size();
            }
            return keyCount;
        }

        for (int i = 0; i < sz; i++) {
            Node* u = q.front();
            q.pop();

            if (u->isLeaf != true) {
                for (Node* v : u->ptr2TreeOrData.ptr2Tree) {
                    q.push(v);
                }
            }
        }
        currentLevel++;
    }

    return 0;
}

} // namespace bptree

